effect.shader:
vec4 u_xlat0;
vec4 u_xlat1;
int u_xlati1;
bvec2 u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
bvec2 u_xlatb3;
vec4 u_xlat4;
vec4 u_xlat5;
int u_xlati7;
float u_xlat9;
vec2 u_xlat12;
float u_xlat13;
bool u_xlatb13;
bvec2 u_xlatb14;
vec2 u_xlat15;
bvec2 u_xlatb15;
float u_xlat18;
float u_xlat19;
bool u_xlatb19;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + (-vec2(_center.x, _center.y));
    u_xlat12.xy = vec2(vec2(_evolution, _evolution)) * vec2(10.0, 0.5);
    u_xlat12.x = u_xlat12.x;
    u_xlat12.x = clamp(u_xlat12.x, 0.0, 1.0);
    u_xlat12.x = u_xlat12.x * _soft;
    u_xlatb1.xy = equal(ivec4(int(_loop), int(_direction), int(_loop), int(_loop)), ivec4(1, 1, 0, 0)).xy;
    u_xlatb13 = u_xlat12.y>=(-u_xlat12.y);
    u_xlat18 = fract(abs(u_xlat12.y));
    u_xlat18 = (u_xlatb13) ? u_xlat18 : (-u_xlat18);
    u_xlat18 = (u_xlatb1.x) ? u_xlat18 : _evolution;
    u_xlat13 = log2(u_xlat18);
    u_xlat13 = u_xlat13 * 0.200000003;
    u_xlat13 = exp2(u_xlat13);
    u_xlat13 = u_xlat13 * 0.5 + 0.5;
    u_xlat13 = u_xlat13 * _amplitude;
    u_xlat19 = u_xlat18 * _elastic;
    u_xlat12.x = u_xlat12.x * u_xlat0.y;
    u_xlat12.x = u_xlat19 * 6.28310013 + u_xlat12.x;
    u_xlat12.x = sin(u_xlat12.x);
    u_xlat12.x = u_xlat12.x * u_xlat13;
    u_xlat18 = u_xlat18 * -5.77078009;
    u_xlat18 = exp2(u_xlat18);
    u_xlat12.x = u_xlat12.x * u_xlat18 + 1.0;
    u_xlat12.xy = u_xlat12.xx * vec2(0.5, -0.5) + vec2(0.5, 1.5);
    u_xlat2.yz = u_xlat0.xy * u_xlat12.xy + vec2(_center.x, _center.y);
    u_xlat2.x = (u_xlatb1.y) ? acScreenNorm.x : u_xlat2.y;
    u_xlat2.w = acScreenNorm.y;
    u_xlat12.xy = (int(_direction) != 0) ? u_xlat2.xz : u_xlat2.yw;
    u_xlatb13 = int(_keep_edge)==1;
    u_xlat2.xy = u_xlat12.xy + vec2(-0.5, -0.5);
    u_xlat2.xy = u_xlat2.xy * vec2(1.00999999, 1.00999999) + vec2(0.5, 0.5);
    u_xlatb14.xy = lessThan(u_xlat2.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb3.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat2.xyxx).xy;
    u_xlat15.xy = fract(u_xlat2.xy);
    u_xlat15.xy = (-u_xlat15.xy) + vec2(1.0, 1.0);
    u_xlat3.x = (u_xlatb3.x) ? u_xlat15.x : u_xlat2.x;
    u_xlat3.y = (u_xlatb3.y) ? u_xlat15.y : u_xlat2.y;
    {
        vec4 hlslcc_movcTemp = u_xlat2;
        hlslcc_movcTemp.x = (u_xlatb14.x) ? (-u_xlat2.x) : u_xlat3.x;
        hlslcc_movcTemp.y = (u_xlatb14.y) ? (-u_xlat2.y) : u_xlat3.y;
        u_xlat2 = hlslcc_movcTemp;
    }
    u_xlat2.xy = u_xlat2.xy + vec2(-0.5, -0.5);
    u_xlat2.xy = u_xlat2.xy * vec2(0.990099013, 0.990099013) + vec2(0.5, 0.5);
    u_xlat12.xy = (bool(u_xlatb13)) ? u_xlat2.xy : u_xlat12.xy;
    u_xlat2 = texture(inputImg, u_xlat12.xy);
    u_xlatb19 = 0<int(_enable_motion_blur);
    if(u_xlatb19){
        u_xlat3.xy = vec2(vec2(_prev_evolution, _prev_evolution)) * vec2(10.0, 0.5);
        u_xlat3.x = u_xlat3.x;
        u_xlat3.x = clamp(u_xlat3.x, 0.0, 1.0);
        u_xlat19 = u_xlat3.x * _soft;
        u_xlatb3.x = u_xlat3.y>=(-u_xlat3.y);
        u_xlat9 = fract(abs(u_xlat3.y));
        u_xlat3.x = (u_xlatb3.x) ? u_xlat9 : (-u_xlat9);
        u_xlat1.x = (u_xlatb1.x) ? u_xlat3.x : _prev_evolution;
        u_xlat3.x = log2(u_xlat1.x);
        u_xlat3.x = u_xlat3.x * 0.200000003;
        u_xlat3.x = exp2(u_xlat3.x);
        u_xlat3.x = u_xlat3.x * 0.5 + 0.5;
        u_xlat3.x = u_xlat3.x * _amplitude;
        u_xlat9 = u_xlat1.x * _elastic;
        u_xlat19 = u_xlat0.y * u_xlat19;
        u_xlat19 = u_xlat9 * 6.28310013 + u_xlat19;
        u_xlat19 = sin(u_xlat19);
        u_xlat19 = u_xlat19 * u_xlat3.x;
        u_xlat1.x = u_xlat1.x * -5.77078009;
        u_xlat1.x = exp2(u_xlat1.x);
        u_xlat1.x = u_xlat19 * u_xlat1.x + 1.0;
        u_xlat1.xw = u_xlat1.xx * vec2(0.5, -0.5) + vec2(0.5, 1.5);
        u_xlat3.yz = u_xlat0.xy * u_xlat1.xw + vec2(_center.x, _center.y);
        u_xlat3.x = (u_xlatb1.y) ? acScreenNorm.x : u_xlat3.y;
        u_xlat3.w = acScreenNorm.y;
        u_xlat0.xy = (int(_direction) != 0) ? u_xlat3.xz : u_xlat3.yw;
        u_xlat1.xy = u_xlat0.xy + vec2(-0.5, -0.5);
        u_xlat1.xy = u_xlat1.xy * vec2(1.00999999, 1.00999999) + vec2(0.5, 0.5);
        u_xlatb3.xy = lessThan(u_xlat1.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
        u_xlatb15.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat1.xyxy).xy;
        u_xlat4.xy = fract(u_xlat1.xy);
        u_xlat4.xy = (-u_xlat4.xy) + vec2(1.0, 1.0);
        u_xlat15.x = (u_xlatb15.x) ? u_xlat4.x : u_xlat1.x;
        u_xlat15.y = (u_xlatb15.y) ? u_xlat4.y : u_xlat1.y;
        {
            vec4 hlslcc_movcTemp = u_xlat1;
            hlslcc_movcTemp.x = (u_xlatb3.x) ? (-u_xlat1.x) : u_xlat15.x;
            hlslcc_movcTemp.y = (u_xlatb3.y) ? (-u_xlat1.y) : u_xlat15.y;
            u_xlat1 = hlslcc_movcTemp;
        }
        u_xlat1.xy = u_xlat1.xy + vec2(-0.5, -0.5);
        u_xlat1.xy = u_xlat1.xy * vec2(0.990099013, 0.990099013) + vec2(0.5, 0.5);
        u_xlat0.xy = (bool(u_xlatb13)) ? u_xlat1.xy : u_xlat0.xy;
        u_xlat0.xy = (-u_xlat0.xy) + u_xlat12.xy;
        u_xlati1 = int(_samples) + int(0xFFFFFFFFu);
        u_xlat1.x = float(u_xlati1);
        u_xlat3 = u_xlat2;
        for(int u_xlati_loop_1 = 0 ; u_xlati_loop_1<int(_samples) ; u_xlati_loop_1++)
        {
            u_xlat13 = float(u_xlati_loop_1);
            u_xlat13 = u_xlat13 / u_xlat1.x;
            u_xlat4.xy = (-u_xlat0.xy) * vec2(u_xlat13);
            u_xlat4.xy = (-u_xlat4.xy) * vec2(_length) + u_xlat12.xy;
            u_xlat4 = texture(inputImg, u_xlat4.xy);
            u_xlat5.z = u_xlat13 * 3.0 + -1.5;
            u_xlat5.y = -abs(u_xlat5.z) + 1.0;
            u_xlat5.x = (-u_xlat5.z);
            u_xlat5.xyz = u_xlat5.xyz;
            u_xlat5.xyz = clamp(u_xlat5.xyz, 0.0, 1.0);
            u_xlat5.xyz = u_xlat4.xyz * u_xlat5.xyz;
            u_xlat5.xyz = u_xlat5.xyz * vec3(3.0, 3.0, 3.0) + (-u_xlat4.xyz);
            u_xlat4.xyz = vec3(vec3(_dispersion, _dispersion, _dispersion)) * u_xlat5.xyz + u_xlat4.xyz;
            u_xlat3 = u_xlat3 + u_xlat4;
        }
        u_xlat0.x = float(int(_samples));
        u_xlat2 = u_xlat3 / u_xlat0.xxxx;
    }
    if(int(_use_inner_mask) != 0) {
        u_xlat0 = texture(inputImg, acScreenNorm.xy);
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat2;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat1.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat2;
    }
    return;
}
